    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address who, uint amount) public payable {
        require(amount > 0, "amount must be positive");
        uint balBefore = c.balances(who); if (__ESBMC_reverted()) return;
        uint cEthBefore = address(c).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint cEthAfter = address(c).balance;
        uint afterBal = c.balances(who); if (__ESBMC_reverted()) return;
        assert(reverted || (afterBal == 0 && cEthAfter == cEthBefore - balBefore));
    }

    receive() external payable {}
}

