pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address who, uint256 amount) internal {
        vm.assume(amount > 0);
        uint256 balBefore;
        try c.balances(who) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint cEthBefore = address(c).balance;
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint cEthAfter = address(c).balance;
        uint256 afterBal;
        try c.balances(who) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(reverted || (afterBal == 0 && cEthAfter == cEthBefore - balBefore));
    }

    function testFuzz_run(address who, uint256 amount) public {
